import struct, socket

def parse_dns_response(data: bytes):
    if len(data) < 12:
        return None
    tid, flags, qdcount, ancount, nscount, arcount = struct.unpack('!HHHHHH', data[:12])
    offset = 12

    def parse_name(offset: int) -> tuple[str, int]:
        labels = []
        initial_offset = offset
        jumped = False
        max_jumps = 20
        jumps = 0
        while True:
            if offset >= len(data):
                break
            length = data[offset]
            if length == 0:
                if not jumped:
                    offset += 1
                break
            elif (length & 0xC0) == 0xC0:
                if offset + 1 >= len(data):
                    break
                pointer = ((length & 0x3F) << 8) | data[offset + 1]
                if not jumped:
                    initial_offset = offset + 2
                    jumped = True
                jumps += 1
                if jumps > max_jumps or pointer >= len(data):
                    break
                offset = pointer
            else:
                offset += 1
                if offset + length > len(data):
                    break
                label = data[offset:offset + length].decode('utf-8', errors='replace')
                labels.append(label)
                offset += length
                if not jumped:
                    initial_offset = offset
        return '.'.join(labels), (initial_offset if jumped else offset)

    # Skip questions
    questions = []
    for _ in range(qdcount):
        qname, offset = parse_name(offset)
        if offset + 4 > len(data):
            break
        qtype, qclass = struct.unpack('!HH', data[offset:offset+4])
        offset += 4
        questions.append((qname, qtype, qclass))

    records = []
    total_records = ancount + nscount + arcount
    for _ in range(total_records):
        if offset >= len(data):
            break
        rname, offset = parse_name(offset)
        if offset + 10 > len(data):
            break
        rtype, rclass, ttl, rdlength = struct.unpack('!HHIH', data[offset:offset+10])
        offset += 10
        rdata = data[offset:offset+rdlength]

        parsed_rdata = None
        if rtype == 12: # PTR
            parsed_rdata, _ = parse_name(offset)
        elif rtype == 1: # A
            if len(rdata) == 4:
                parsed_rdata = socket.inet_ntoa(rdata)
        elif rtype == 33: # SRV
            if len(rdata) >= 6:
                priority, weight, port = struct.unpack('!HHH', rdata[:6])
                target, _ = parse_name(offset + 6)
                parsed_rdata = {'priority': priority, 'weight': weight, 'port': port, 'target': target}
        elif rtype == 16: # TXT
            txt_dict = {}
            pos = 0
            while pos < len(rdata):
                txt_len = rdata[pos]
                pos += 1
                item = rdata[pos:pos+txt_len]
                pos += txt_len
                if b'=' in item:
                    k, v = item.split(b'=', 1)
                    txt_dict[k.decode('utf-8', errors='replace')] = v.decode('utf-8', errors='replace')
                elif item:
                    txt_dict[item.decode('utf-8', errors='replace')] = ''
            parsed_rdata = txt_dict

        records.append({
            'name': rname,
            'type': rtype,
            'class': rclass & 0x7FFF,
            'ttl': ttl,
            'data': parsed_rdata
        })
        offset += rdlength

    return {'questions': questions, 'records': records}

print('Parser logic compiles cleanly.')
