from typing import Dict, List, Any

class MdnsDeviceAggregator:
    def __init__(self):
        # instance -> info
        self.instances: Dict[str, Dict[str, Any]] = {}
        # host -> ip
        self.host_to_ip: Dict[str, str] = {}
        # instance -> service_type
        self.instance_service: Dict[str, str] = {}

    def ingest_records(self, records: List[Dict[str, Any]], sender_ip: str):
        for r in records:
            rtype = r['type']
            rname = r['name']
            rdata = r['data']

            if rtype == 12: # PTR
                instance = rdata
                if instance not in self.instances:
                    self.instances[instance] = {'port': 5555, 'target': '', 'txt': {}, 'ip': sender_ip}
                self.instance_service[instance] = rname
            elif rtype == 33: # SRV
                instance = rname
                if instance not in self.instances:
                    self.instances[instance] = {'port': 5555, 'target': '', 'txt': {}, 'ip': sender_ip}
                if isinstance(rdata, dict):
                    self.instances[instance]['port'] = rdata.get('port', 5555)
                    target = rdata.get('target', '')
                    self.instances[instance]['target'] = target
                    if target in self.host_to_ip:
                        self.instances[instance]['ip'] = self.host_to_ip[target]
            elif rtype == 16: # TXT
                instance = rname
                if instance not in self.instances:
                    self.instances[instance] = {'port': 5555, 'target': '', 'txt': {}, 'ip': sender_ip}
                if isinstance(rdata, dict):
                    self.instances[instance]['txt'].update(rdata)
            elif rtype == 1: # A
                host = rname
                ip = rdata
                self.host_to_ip[host] = ip
                for inst, info in self.instances.items():
                    if info.get('target') == host:
                        info['ip'] = ip

    def get_devices(self) -> List[Dict[str, Any]]:
        devices = []
        for instance, info in self.instances.items():
            base_name = instance
            for suffix in ['._adb._tcp.local', '._adb-tls-connect._tcp.local', '._tcp.local', '.local']:
                if base_name.endswith(suffix):
                    base_name = base_name[:-len(suffix)]
                    break
            txt = info['txt']
            model = txt.get('model') or txt.get('device') or ''
            friendly_name = txt.get('name') or base_name
            devices.append({
                'ip': info['ip'],
                'port': info['port'],
                'name': friendly_name,
                'model': model,
                'service_type': self.instance_service.get(instance, '_adb._tcp.local'),
                'attributes': txt
            })
        return devices

